const { PriorityQueue } = require("@datastructures-js/priority-queue");
const input = require("fs").readFileSync(0, "utf8");
const [kLine, numsLine] = input.trim().split("\n");
const k = Number(kLine);
const nums = numsLine.trim().split(/\s+/).map(Number);

const counts = new Map();
for (const n of nums) {
  counts.set(n, (counts.get(n) ?? 0) + 1);
}
const heap = new PriorityQueue((a, b) => a[1] - b[1] || b[0] - a[0]);
for (const pair of counts) {
  heap.enqueue(pair);
  if (heap.size() > k) {
    heap.dequeue();
  }
}
const best = [];
while (!heap.isEmpty()) {
  best.push(heap.dequeue());
}
best.reverse();

for (const [num, count] of best) {
  console.log(`${num} x${count}`);
}

steps.body:
BFS finds the path with the fewest edges, but when edges have weights (minutes, prices), fewer edges can cost more. **Dijkstra's algorithm** finds the cheapest paths from a start node with a min-heap of `[distance, node]` pairs:

1. Every distance starts at `Infinity`, except the start at 0. Push `[0, start]`.
2. Dequeue the closest pair. If its distance is bigger than the best known for that node, it is stale: skip it.
3. For each edge to `next` with weight `w`, if `d + w` beats the best known distance to `next`, record it and push `[d + w, next]`.

```javascript harness
const { MinPriorityQueue, MaxPriorityQueue, PriorityQueue } = require("@datastructures-js/priority-queue");
const graph = new Map([["A", [["B", 4], ["C", 1]]], ["C", [["B", 2]]], ["B", []]]);
const dist = new Map([["A", 0]]);
const heap = new PriorityQueue((a, b) => a[0] - b[0]);
heap.enqueue([0, "A"]);
{{code}}
console.log(JSON.stringify([...dist]));
```

```javascript
while (!heap.isEmpty()) {
  const [d, node] = heap.dequeue();
  if (d > dist.get(node)) {
    continue;
  }
  for (const [next, w] of graph.get(node)) {
    if (d + w < (dist.get(next) ?? Infinity)) {
      dist.set(next, d + w);
      heap.enqueue([d + w, next]);
    }
  }
}
```

The adjacency Map holds `[next, weight]` pairs. A node can sit in the heap more than once, and the stale check makes sure only its best entry counts. `dist.get(next) ?? Infinity` treats a node with no distance yet as infinitely far. The algorithm needs weights of 0 or more.

To print the path, keep a `parent` Map and set `parent.set(next, node)` whenever you improve `next`. Then walk back from the target and reverse, as with BFS paths.

**The gotcha:** a node that never gets a distance was never reached. Report it as unreachable instead of printing `undefined` or `Infinity`.

example.code:
const { PriorityQueue } = require("@datastructures-js/priority-queue");
const input = require("fs").readFileSync(0, "utf8");
const [start, ...roads] = input.trim().split("\n").map((line) => line.trim());

const graph = new Map();
for (const road of roads) {
  const [a, b, minutes] = road.split(/\s+/);
  for (const place of [a, b]) {
    if (!graph.has(place)) {
      graph.set(place, []);
    }
  }
  graph.get(a).push([b, Number(minutes)]);
  graph.get(b).push([a, Number(minutes)]);
}

const dist = new Map([[start, 0]]);
const heap = new PriorityQueue((a, b) => a[0] - b[0]);
heap.enqueue([0, start]);
while (!heap.isEmpty()) {
  const [d, place] = heap.dequeue();
  if (d > dist.get(place)) {
    continue;
  }
  for (const [next, w] of graph.get(place)) {
    if (d + w < (dist.get(next) ?? Infinity)) {
      dist.set(next, d + w);
      heap.enqueue([d + w, next]);
    }
  }
}

for (const place of [...graph.keys()].sort()) {
  console.log(`${place}: ${dist.has(place) ? dist.get(place) : "unreachable"}`);
}

