const { PriorityQueue } = require("@datastructures-js/priority-queue");
const input = require("fs").readFileSync(0, "utf8");
const [first, ...flights] = input.trim().split("\n").map((line) => line.trim());
const [from, to] = first.split(/\s+/);

const graph = new Map();
for (const flight of flights) {
  const [a, b, cost] = flight.split(/\s+/);
  if (!graph.has(a)) {
    graph.set(a, []);
  }
  graph.get(a).push([b, Number(cost)]);
}

const dist = new Map([[from, 0]]);
const parent = new Map();
const heap = new PriorityQueue((a, b) => a[0] - b[0]);
heap.enqueue([0, from]);
while (!heap.isEmpty()) {
  const [d, node] = heap.dequeue();
  if (d > dist.get(node)) {
    continue;
  }
  for (const [next, w] of graph.get(node) ?? []) {
    if (d + w < (dist.get(next) ?? Infinity)) {
      dist.set(next, d + w);
      parent.set(next, node);
      heap.enqueue([d + w, next]);
    }
  }
}

if (!dist.has(to)) {
  console.log("no route");
} else {
  const route = [to];
  while (route[route.length - 1] !== from) {
    route.push(parent.get(route[route.length - 1]));
  }
  route.reverse();
  console.log(`${dist.get(to)}: ${route.join(" -> ")}`);
}
